export function listTerrariaItems(): TerrariaItemCatalogEntry[] {
  return TERRARIA_ITEM_CATALOG.map((item) => ({ ...item, aliases: [...item.aliases] }));
}

export function resolveTerrariaItemCode(input: string): string {
  const normalized = normalizeItemAlias(input);
  const match = TERRARIA_ITEM_CATALOG.find((item) =>
    item.code === input.trim()
    || normalizeItemAlias(item.name) === normalized
    || item.aliases.some((alias) => normalizeItemAlias(alias) === normalized),
  );
  return match?.code ?? input.trim();
}

function normalizeItemAlias(input: string): string {
  return input.trim().toLowerCase().replace(/[^a-z0-9]+/g, '');
}
